import pandas as pd

# parse logs generated by energy_test.sh

def parse_log(path):
    data = []
    with open(path) as f:
        for line in f:
            name, cpu, mem = line.strip().split()[:3]
            cpu_val = float(cpu.strip('%'))
            mem_val = mem.split('/')[0]
            data.append({'name': name, 'cpu': cpu_val, 'mem': mem_val})
    return pd.DataFrame(data)

if __name__ == '__main__':
    df_snn = parse_log('snn_stats.log')
    df_lstm = parse_log('lstm_stats.log')
    print(df_snn.head())
    print(df_lstm.head())
